use clap::ValueEnum;

/// Content generated by the mock server for ARTICLE and BODY responses.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, ValueEnum)]
pub enum PayloadMode {
    /// Deterministic binary data encoded with yEnc, including its checksum.
    #[default]
    Yenc,
    /// Repeated readable text.
    Plain,
}

pub(crate) fn encode_yenc_payload(size: usize) -> Box<[u8]> {
    // The encoder's one-based input range does not represent an empty file.
    if size == 0 {
        return b"=ybegin line=128 size=0 name=nntpbench.bin\r\n=yend size=0 crc32=00000000\r\n"
            .to_vec()
            .into_boxed_slice();
    }
    let mut random = 0x7ac3_85d1u32;
    let decoded: Vec<u8> = (0..size)
        .map(|_| {
            random ^= random << 13;
            random ^= random >> 17;
            random ^= random << 5;
            random.to_le_bytes()[0]
        })
        .collect();
    let mut encoded = Vec::new();
    yenc::EncodeOptions::new()
        .begin(1)
        .end(u64::try_from(size).expect("payload size fits u64"))
        .encode_stream(
            std::io::Cursor::new(&decoded),
            &mut encoded,
            u64::try_from(size).expect("payload size fits u64"),
            "nntpbench.bin",
        )
        .expect("default yEnc options and writes to Vec cannot fail");
    encoded.into_boxed_slice()
}
